def re_arrange(arr, n):
    pos = []
    neg = []
    for i in range(n):
        if arr[i] < 0:
            neg.append(arr[i])
        else:
            pos.append(arr[i])
    ans = []
    for i in range(n):
        if i % 2 == 0:
            if neg:
                ans.append(neg.pop())
            else:
                ans.append(pos.pop())
        else:
            if pos:
                ans.append(pos.pop())
            else:
                ans.append(neg.pop())
    return ans

