def num_comm_div(a, b):
    # Find the smaller number between a and b
    smaller = min(a, b)

    # Initialize a list to store common divisors
    common_divisors = []

    # Iterate through numbers from 1 to the smaller number
    for i in range(1, smaller + 1):
        # Check if both a and b are divisible by i
        if a % i == 0 and b % i == 0:
            # If so, add i to the list of common divisors
            common_divisors.append(i)

    # Return the largest common divisor
    return max(common_divisors)

def permutation_coefficient(n, k):
    if k == 0:
        return 1
    return n * permutation_coefficient(n - 1, k - 1)

def count_element_freq(tup):
    freq_dict = {}
    for item in tup:
        if isinstance(item, tuple):
            for sub_item in item:
                freq_dict[sub_item] = freq_dict.get(sub_item, 0) + 1
        else:
            freq_dict[item] = freq_dict.get(item, 0) + 1
    return freq_dict
